"""工位系统.xlsx: 汇总 and 产品描述. Names are shortened for the shop UI.

Location descriptions are source art direction, not composite-ready assets.
"""
UPGRADE_COSTS = (20, 40, 70, 120, 200, 300, 400, 600, 800)
# Whole environment income, repeated for the two internal appearance tiers.
ENVIRONMENT_INCOME = (0, 0, 2, 2, 5, 5, 10, 10, 20, 20)


def component_daily_income(number, level, equipped=True, *, rules=None):
    if not equipped:
        return 0
    if number >= 6:
        return (rules['tool_income'] if rules else TOOL_INCOME)[level - 1]
    # Keep integer snapshots/ledger amounts while preserving the five bundled
    # component records. Their sum is exactly the whole-environment income.
    total = rules['environment_income'][(level - 1) // 2] if rules else ENVIRONMENT_INCOME[level - 1]
    quotient, remainder = divmod(total, 5)
    return quotient + (number <= remainder)

TOOL_INCOME = (0, 2, 5, 10, 15, 20, 25, 30, 35, 40)


def upgrade_cost(from_level, to_level=None, *, rules=None):
    """Return the workbook price for one or more consecutive level upgrades."""
    if to_level is None:
        to_level = from_level + 1
    if not (1 <= from_level <= to_level <= len(UPGRADE_COSTS) + 1):
        raise ValueError(f"invalid upgrade range: {from_level}->{to_level}")
    return sum((rules['upgrade_costs'] if rules else UPGRADE_COSTS)[from_level - 1:to_level - 1])


def environment_daily_income(environment, *, rules=None):
    """Daily income for one five-item environment bundle."""
    if not 1 <= environment <= 5:
        raise ValueError(f"invalid environment: {environment}")
    return rules['environment_income'][environment - 1] if rules else ENVIRONMENT_INCOME[environment * 2 - 2]


def environment_upgrade_cost(environment, *, rules=None):
    """Price for moving the five bundled environment items to the next level."""
    if not 1 <= environment < 5:
        raise ValueError(f"invalid environment upgrade: {environment}")
    return 5 * upgrade_cost(environment * 2 - 1, environment * 2 + 1, rules=rules)


