def component_name(category, level, *, rules=None):
    names = rules['device_names'].get(category['key']) if rules and category['number'] >= 6 else None
    return (names or category['names'])[level - 1]


def environment_name(environment, *, rules=None):
    from .workstation_labels import ENVIRONMENT_NAMES
    return (rules['environment_names'] if rules else ENVIRONMENT_NAMES)[environment - 1]
